/**
 * Cloudflare Worker: s3-image-proxy
 * Route: assets.natur-savon.com.ua/*
 *
 * Serves product images from the public S3 bucket and caches them at the Cloudflare edge.
 * No credentials needed — the bucket policy allows public reads.
 *
 * Caching strategy
 *  - Image URLs generated by the API carry a version: /Title_1.webp?v=<last-modified>.
 *    The version is part of the cache key, so a replaced / re-ordered image gets a new URL
 *    and these URLs are cached "forever" (1 year, immutable).
 *  - Un-versioned URLs (e.g. typed by hand) are cached for 1 hour only.
 *  - Only successful responses are cached; errors (404/5xx) are never cached.
 */
const S3_ORIGIN = 'https://natur-savon-images.s3.eu-north-1.amazonaws.com';

const ONE_YEAR = 31536000;
const ONE_HOUR = 3600;

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',
};

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS_HEADERS });
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method Not Allowed', { status: 405, headers: CORS_HEADERS });
    }
    if (url.pathname === '/' || url.pathname === '') {
      return new Response('Not Found', { status: 404, headers: CORS_HEADERS });
    }

    // The query string (?v=...) is part of the cache key, so versioned URLs never collide.
    const cache = caches.default;
    const cacheKey = new Request(url.toString(), { method: 'GET' });

    if (request.method === 'GET') {
      const cached = await cache.match(cacheKey);
      if (cached) return cached;
    }

    // Keys stay percent-encoded (Cyrillic titles etc.); the query string is NOT sent to S3.
    const s3Response = await fetch(`${S3_ORIGIN}${url.pathname}`, { method: request.method });

    if (!s3Response.ok) {
      // Never cache errors — an image uploaded later must become visible immediately.
      return new Response(s3Response.body, {
        status: s3Response.status,
        headers: { ...CORS_HEADERS, 'Cache-Control': 'no-store' },
      });
    }

    const versioned = url.searchParams.has('v');
    const ttl = versioned ? ONE_YEAR : ONE_HOUR;
    const headers = new Headers({
      'Content-Type': s3Response.headers.get('Content-Type') || 'image/webp',
      'Cache-Control': versioned
        ? `public, max-age=${ttl}, immutable`
        : `public, max-age=${ttl}`,
      ...CORS_HEADERS,
    });
    const etag = s3Response.headers.get('ETag');
    if (etag) headers.set('ETag', etag);

    const response = new Response(s3Response.body, { status: 200, headers });

    if (request.method === 'GET') {
      ctx.waitUntil(cache.put(cacheKey, response.clone()));
    }
    return response;
  },
};

